def itin(name, audience, budget, days, schedule, estimate, backup):
    return {
        "模板名": name,
        "适用人群": audience,
        "预算档": budget,
        "天数": days,
        "逐时段安排": schedule,
        "预算估算": f"{estimate}；已含基础门票和市内交通，长距离包车或水上项目需单独计算。旺季门票和住宿价格波动较大，建议提前确认。",
        "备选方案": f"{backup}；如遇限流、闭馆或天气突变，改同类室内或周边景点，并预留交通缓冲。",
    }


