    faq("怎么避开游客店？", "优先选本地人常去的街区、老字号或当天现做的店。看菜单和分量，避免拉客、远低于市场价的套餐。人多不一定等于好，选新店前先确认口碑。", "美食避坑"),
    faq("一周预算怎么控制？", "把预算分成住宿、交通、门票、餐饮和应急五部分，住宿提前订，交通尽量选高铁或地铁。热门乐园和长距离包车要单独算，不要只看房价。", "预算管理"),
    faq("学生证有优惠吗？", "部分景点对学生、老人、儿童有优惠，但需要有效证件并按现场规定执行。买票前先查官方渠道，不要轻信代购和黄牛，票价可能随时调整。", "门票优惠"),
